const yuan=n=>(Number(n||0)/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const names={dashboard:'工作台',archives:'综合档案',spaces:'车位管理',billing:'收费中心',fees:'费项配置',settings:'系统设置',history:'操作记录'};
