let S, page='dashboard', period='month', archiveKind='houses', filterPath=[], localQuery='', billHouse='', billStatus='unpaid', billItem='', billUntil='', billYear='', tablePage=1, drawerHouse='', drawerTab='houses', auditPreset='year', auditStart='', auditEnd='', auditScope='', auditItem='';
let busy=false, importData=null;
const today=()=>S?.today||new Date().toLocaleDateString('sv-SE');
const house=id=>S.houses.find(x=>x.id===id);
